using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.Filters;using System.Security.Claims;using TEKAManager.Core.Services;
namespace TEKAManager.API.Security;
[AttributeUsage(AttributeTargets.Class|AttributeTargets.Method,AllowMultiple=true)]public sealed class RequirePermissionAttribute(string menu,string permission):Attribute,IAsyncAuthorizationFilter{public async Task OnAuthorizationAsync(AuthorizationFilterContext context){if(context.HttpContext.User.Identity?.IsAuthenticated!=true){context.Result=new UnauthorizedResult();return;}if(!int.TryParse(context.HttpContext.User.FindFirstValue(ClaimTypes.NameIdentifier),out var uid)){context.Result=new UnauthorizedResult();return;}var auth=context.HttpContext.RequestServices.GetRequiredService<IAuthService>();var p=await auth.GetPermisosEfectivosAsync(uid);if(!p.Any(x=>string.Equals(x.MenuNombre,menu,StringComparison.OrdinalIgnoreCase)&&string.Equals(x.PermisoNombre,permission,StringComparison.OrdinalIgnoreCase)))context.Result=new ObjectResult(new{mensaje="No tenés permisos para realizar esta acción."}){StatusCode=StatusCodes.Status403Forbidden};}}
